  - roles/storage.objectCreator  # Write to processed and invalid buckets
  - roles/pubsub.publisher      # Publish to app-logs.events

# Dataflow service account
roles:
  - roles/pubsub.subscriber     # Read from app-logs-events subscription
  - roles/bigquery.dataEditor   # Write to analytics.app_logs
